// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize(); // owner is address(this)
    }

    function testFuzz_property(address actor, address newOwner) public {
        // admissible domain: actor is NOT the owner (address(this)), and the transfer
        // would actually change the owner to a non-zero address
        vm.assume(actor != address(this));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != c.owner());

        address ownerBefore = c.owner();
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // general rule: a non-owner cannot transfer ownership — the call must revert
        // and the owner must remain unchanged.
        assertTrue(!ok && c.owner() == ownerBefore, "non-owner must not transfer ownership");
    }
}
